 42	public actor BackgroundWorker {
 43	    private let root: URL
 44	    private let store: Store
 45	    private let bridge = RuntimeBridge()
 46	    private var state = ServiceStatus()
 47	    private var dirtySince: Date?
 48	    private var lastDirty: Date?
 49	    private var generation = 0
 50	    private var needsScan = true
 51	
 52	    public init(root: URL) throws {
 53	        self.root = root
 54	        store = try Store(path: root.appendingPathComponent("index.sqlite").path)
 55	        if FileManager.default.fileExists(atPath: root.appendingPathComponent("archive-dirty").path) { dirtySince = .distantPast; lastDirty = .distantPast }
 56	    }
 57	    private func publish() throws {
 58	        state.updated = Date()
 59	        try JSONEncoder().encode(state).write(to: root.appendingPathComponent("service-status.json"), options: .atomic)
 60	    }
 61	    private func markDirty() throws {
 62	        dirtySince = dirtySince ?? Date(); lastDirty = Date(); generation += 1
 63	        try Data("pending".utf8).write(to: root.appendingPathComponent("archive-dirty"), options: .atomic)
 64	    }
 65	    private func receive(_ event: String, _ data: JSONValue) {
 66	        do {
 67	            if event == "session", try store.save(data.decode(Session.self)) { try markDirty() }
 68	            if event == "sourceChanged" { needsScan = true }
 69	            if event == "warning" { state.scan = data.string }
 70	            if event == "disconnected" { state.scan = data.string }
 71	        } catch { state.scan = error.localizedDescription }
 72	    }
 73	    public func run(once: Bool = false) async throws {
 74	        let lease = try ServiceLease(root: root)
 75	        defer { withExtendedLifetime(lease) {} }
 76	        await bridge.setHandler { [weak self] event, data in await self?.receive(event, data) }
 77	        try await bridge.start(dataDirectory: root)
 78	        _ = try await bridge.request("initialize")
 79	        var lastScan = Date.distantPast, lastPush = Date.distantPast, lastArchiveAttempt = Date.distantPast, lastRequest: Data?, lastSettings: Data?, lastVersion: Int?
 80	        let encoder = JSONEncoder(); encoder.outputFormatting = [.sortedKeys]
 81	        repeat {
 82	            do {
 83	                let settings = try store.settings()
 84	                if !once && settings.backgroundEnabled != true { break }
 85	                let settingsData = try encoder.encode(settings)
 86	                if settingsData != lastSettings { lastSettings = settingsData; needsScan = true; try markDirty() }
 87	                let version = try store.dataVersion()
 88	                if version != lastVersion { lastVersion = version; try markDirty() }
 89	                let requestPath = root.appendingPathComponent("service-request")
 90	                let request = FileManager.default.fileExists(atPath: requestPath.path) ? try Data(contentsOf: requestPath) : nil
 91	                let requested = request != lastRequest
 92	                if requested { lastRequest = request; needsScan = true; try markDirty() }
 93	                if needsScan || Date().timeIntervalSince(lastScan) >= 60 {
 94	                    needsScan = false; state.scan = "正在扫描"; try publish()
 95	                    let result = try await bridge.request("scan", ["locations": try .encode(settings.locations)], timeout: 600)
 96	                    state.scan = "扫描完成 · \(result["count"].text) 个变更"; lastScan = Date()
 97	                }
 98	                let due = dirtySince.map { Date().timeIntervalSince($0) >= 300 || Date().timeIntervalSince(lastDirty ?? $0) >= 30 } ?? false
 99	                if !settings.archivePath.isEmpty && (once || requested || (due && Date().timeIntervalSince(lastArchiveAttempt) >= 30)) {
100	                    lastArchiveAttempt = Date()
101	                    let current = generation
102	                    state.archive = "正在保存并提交"; try publish()
103	                    let store = self.store
104	                    let result = try await Task.detached(priority: .utility) {
105	                        let sessions = try store.list().filter { !settings.excludedProjects.contains($0.project) }.compactMap { try store.session($0.id) }
106	                        return try Archive.save(sessions, to: URL(fileURLWithPath: settings.archivePath), sourceRoots: settings.locations.map(\.path))
107	                    }.value
108	                    state.archive = result.commit.map { "本地归档已提交 · \($0)" } ?? "本地归档已是最新"
109	                    state.lastArchive = Date()
110	                    if current == generation { dirtySince = nil; try FileManager.default.removeItem(at: root.appendingPathComponent("archive-dirty")) }
111	                    if settings.archiveRemote != nil { try Data("pending".utf8).write(to: root.appendingPathComponent("sync-pending"), options: .atomic); lastPush = .distantPast }
112	                }
113	                if let remote = settings.archiveRemote, !settings.archivePath.isEmpty,
114	                   FileManager.default.fileExists(atPath: root.appendingPathComponent("sync-pending").path), Date().timeIntervalSince(lastPush) >= 60 {
115	                    lastPush = Date(); state.sync = "正在推送"; try publish()
116	                    do {
117	                        _ = try await Task.detached(priority: .utility) { try ArchiveSync.push(root: URL(fileURLWithPath: settings.archivePath), remote: remote.remote, branch: remote.branch) }.value
118	                        try FileManager.default.removeItem(at: root.appendingPathComponent("sync-pending"))
119	                        state.sync = "已推送到 \(remote.remote)/\(remote.branch)"
120	                    } catch { state.sync = "推送待重试：\(error.localizedDescription)" }
121	                }
122	                if settings.archiveRemote == nil { state.sync = "未启用远端推送" }
123	                try publish()
124	            } catch {
125	                state.archive = "处理失败：\(error.localizedDescription)"; try publish()
126	                if once { await bridge.close(); throw error }
127	            }
128	            if once { break }
129	            try await Task.sleep(for: .seconds(2))
130	        } while !Task.isCancelled
131	        await bridge.close()
132	    }
133	}

