 14	export async function migrateSession(value: unknown): Promise<Session> {
 15	  const input = object(value), source = object(input.session), target = object(input.target);
 16	  const kind = string(target.kind), home = string(input.home), cwd = string(input.cwd);
 17	  if (!['codex', 'claude', 'dsh'].includes(kind) || !isAbsolute(home) || !isAbsolute(cwd) || !string(source.id)
 18	    || !['codex', 'claude', 'dsh', 'desktop', 'acp'].includes(string(source.source))
 19	    || !Array.isArray(source.files) || !Array.isArray(source.messages) || !Array.isArray(target.args)
 20	    || target.args.some(x => typeof x !== 'string') || !string(target.command) || !string(target.id)) throw new Error('迁移来源、目标工具或目录无效');
 21	  if (Object.entries(object(target.env)).some(([key, value]) => !/^[A-Za-z_][A-Za-z0-9_]*$/.test(key) || typeof value !== 'string')) throw new Error('目标工具环境变量无效');
 22	  if (!(await stat(cwd)).isDirectory()) throw new Error('目标项目不是目录');
 23	  const files = source.files;
 24	  if (files.some(p => typeof p !== 'string' || !isAbsolute(p))) throw new Error('源记录路径无效');
 25	  const id = randomUUID(), now = Date.now();
 26	  const history: Historical[] = [], snapshots: { path: string; data: Buffer; fingerprint: string }[] = [];
 27	  const attachments = new Set<string>();
 28	  if (source.source === 'acp' || source.source === 'desktop') {
 29	    for (const raw of source.messages) {
 30	      const message = object(raw);
 31	      if (typeof message.text !== 'string') throw new Error('源消息内容无效');
 32	      history.push({ role: message.role === 'user' ? 'user' : 'assistant', text: message.text, time: timestamp(message.time) || now });
 33	    }
 34	  }
 35	  const collectAttachments = (v: unknown): void => {
 36	    if (Array.isArray(v)) { for (const item of v) collectAttachments(item); return; }
 37	    const record = object(v), type = string(record.type);
 38	    for (const [key, item] of Object.entries(record)) {
 39	      if (typeof item === 'string' && item.startsWith('file://')) attachments.add(fileURLToPath(item));
 40	      else if (typeof item === 'string' && isAbsolute(item) && /image|file|attachment/.test(type) && /path|url|image/.test(key)) attachments.add(item);
 41	      else if (typeof item === 'object' && item !== null) collectAttachments(item);
 42	    }
 43	  };
 44	  for (const path of files as string[]) {
 45	    const before = await stat(path);
 46	    if (!before.isFile()) throw new Error(`源记录不是普通文件：${path}`);
 47	    const data = await readFile(path);
 48	    const fingerprint = `${before.size}:${before.mtimeMs}`;
 49	    snapshots.push({ path, data, fingerprint });
 50	    if (!/\.jsonl(?:\.(?:zstd|zst))?$|\.json$/i.test(path)) { attachments.add(path); continue; }
 51	    const text = (/\.(zstd|zst)$/.test(path) ? zstdDecompressSync(data) : data).toString('utf8');
 52	    const records: unknown[] = /\.json$/i.test(path) ? [JSON.parse(text)] : text.split('\n').filter(line => line.trim()).map(line => JSON.parse(line));
 53	    for (const raw of records) {
 54	      const e = object(raw);
 55	      if (!Object.keys(e).length) throw new Error(`源记录格式无效：${path}`);
 56	      collectAttachments(e);
 57	      const p = object(e.payload), d = object(e.data), m = object(e.message);
