140	      }
141	      if (e.type === 'tool/call') addMessage('tool', `${string(d.name)}\n${content(d.arguments)}`, String(e.seq), 'tool');
142	      if (e.type === 'tool/result') addMessage('tool', content(d.result ?? d.content), String(e.seq), 'tool');
